local function b64decode(data)
    data = data:gsub("%s+", "")
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local out = {}
    local bits, value = 0, 0
    for i = 1, #data do
        local c = data:sub(i, i)
        if c ~= "=" then
            local p = chars:find(c, 1, true)
            if p then
                value = value * 64 + (p - 1)
                bits = bits + 6
                if bits >= 8 then
                    bits = bits - 8
                    out[#out + 1] = string.char(math.floor(value / 2^bits) % 256)
                end
            end
        end
    end
    return table.concat(out)
end

local function getParent()
    local ok, cg = pcall(function() return gethui() end)
    if ok and cg then return cg end
    return CoreGui
end

local old = getgenv and getgenv().LeakDHubProSelector
if old and old.Destroy then
    pcall(old.Destroy)
end

local state = {alive = true, connections = {}, instances = {}}
local function track(x)
    state.instances[#state.instances + 1] = x
    return x
end
local function connect(signal, fn)
    local c = signal:Connect(fn)
    state.connections[#state.connections + 1] = c
    return c
end
local function cleanup()
    if not state.alive then return end
    state.alive = false
    for _, c in ipairs(state.connections) do pcall(function() c:Disconnect() end) end
    for i = #state.instances, 1, -1 do pcall(function() state.instances[i]:Destroy() end) end
    if getgenv then getgenv().LeakDHubProSelector = nil end
end
state.Destroy = cleanup
if getgenv then getgenv().LeakDHubProSelector = state end

