local function makeCard(name, imageData, accent, titleText, descText)
    local card = track(Instance.new("Frame"))
    card.Name = name
    card.BackgroundColor3 = Color3.fromRGB(18, 18, 22)
    card.BorderSizePixel = 0
    card.Parent = cards
    track(Instance.new("UICorner", card)).CornerRadius = UDim.new(0, 20)

    local s = track(Instance.new("UIStroke", card))
    s.Thickness = 2
    s.Color = accent
    s.Transparency = 0.28

    local img = track(Instance.new("ImageLabel"))
    img.BackgroundColor3 = Color3.fromRGB(7, 7, 9)
    img.BackgroundTransparency = 0
    img.AnchorPoint = Vector2.new(0.5, 0)
    img.Position = UDim2.fromScale(0.5, 0.035)
    img.Size = UDim2.fromScale(0.91, 0.59)
    img.Image = imageData
    img.ScaleType = Enum.ScaleType.Crop
    img.Parent = card
    track(Instance.new("UICorner", img)).CornerRadius = UDim.new(0, 16)

    local bar = track(Instance.new("Frame"))
    bar.BackgroundColor3 = accent
    bar.BorderSizePixel = 0
    bar.Position = UDim2.fromScale(0.08, 0.66)
    bar.Size = UDim2.fromScale(0.84, 0.012)
    bar.Parent = card
    track(Instance.new("UICorner", bar)).CornerRadius = UDim.new(1, 0)

    local t = track(Instance.new("TextLabel"))
    t.BackgroundTransparency = 1
    t.Position = UDim2.fromScale(0.07, 0.695)
    t.Size = UDim2.fromScale(0.86, 0.09)
    t.Font = Enum.Font.GothamBlack
    t.Text = titleText
    t.TextColor3 = Color3.fromRGB(255, 245, 230)
    t.TextScaled = true
    t.Parent = card

    local d = track(Instance.new("TextLabel"))
    d.BackgroundTransparency = 1
    d.Position = UDim2.fromScale(0.07, 0.79)
    d.Size = UDim2.fromScale(0.86, 0.075)
    d.Font = Enum.Font.GothamMedium
    d.Text = descText
    d.TextColor3 = Color3.fromRGB(190, 190, 198)
    d.TextScaled = true
    d.Parent = card

    local button = track(Instance.new("TextButton"))
    button.BackgroundColor3 = accent
    button.BackgroundTransparency = 0.08
    button.Position = UDim2.fromScale(0.07, 0.885)
    button.Size = UDim2.fromScale(0.86, 0.085)
    button.AutoButtonColor = false
    button.Font = Enum.Font.GothamBlack
    button.Text = "CHỌN MENU"
    button.TextColor3 = Color3.fromRGB(10, 10, 10)
    button.TextScaled = true
    button.Parent = card
    track(Instance.new("UICorner", button)).CornerRadius = UDim.new(0, 12)

    local hover = false
    connect(button.MouseEnter, function()
        hover = true
        TweenService:Create(button, TweenInfo.new(0.16), {BackgroundTransparency = 0}):Play()
        TweenService:Create(card, TweenInfo.new(0.16), {Size = UDim2.fromScale(1.02, 1.02)}):Play()
    end)
    connect(button.MouseLeave, function()
        hover = false
        TweenService:Create(button, TweenInfo.new(0.16), {BackgroundTransparency = 0.08}):Play()
        TweenService:Create(card, TweenInfo.new(0.16), {Size = UDim2.fromScale(1, 1)}):Play()
    end)

    return button
end

-- Ảnh local: nếu executor hỗ trợ getcustomasset/writefile, selector sẽ dùng đúng ảnh người dùng gửi.
local function localAsset(filename, encoded)
    if not (writefile and getcustomasset) then return "" end
    local path = "LeakDHubPro/" .. filename
    pcall(function()
        if not isfile or not isfile(path) then
            if not isfolder or not isfolder("LeakDHubPro") then
                pcall(makefolder, "LeakDHubPro")
            end
            writefile(path, b64decode(encoded))
        end
    end)
    local ok, asset = pcall(getcustomasset, path)
    return ok and asset or ""
end

