-- Hiệu ứng nhẹ: chỉ chạy ở bộ chọn, tự ngắt khi chọn.
local t0 = os.clock()
connect(RunService.RenderStepped, function()
    if not state.alive then return end
    local t = os.clock() - t0
    local pulse = 0.5 + math.sin(t * 3.2) * 0.5
    glow.BackgroundTransparency = 0.94 - pulse * 0.035
    stroke.Transparency = 0.20 + pulse * 0.16
    title.TextTransparency = pulse * 0.04
end)

local VENYX_CODE = ""
local CHILLI_CODE = ""

local function runCode(encoded)
    cleanup()
    task.defer(function()
        local source = b64decode(encoded)
        local fn, err = loadstring(source)
        if not fn then
            warn("LeakD Hub Pro: không thể tải menu: " .. tostring(err))
            return
        end
        local ok, result = pcall(fn)
        if not ok then
            warn("LeakD Hub Pro: lỗi khi chạy menu: " .. tostring(result))
        end
    end)
end

connect(chilliButton.MouseButton1Click, function()
    runCode(CHILLI_CODE)
end)

connect(venyxButton.MouseButton1Click, function()
    runCode(VENYX_CODE)
end)

